-- rollback: restore dispatch implementations before repointing the catalog in a new migration.
-- expand-contract: control metadata only; preserve rule definitions, bindings and receipts.
-- lock-review: one primary-key catalog upsert; approved-control rewrite guards remain active.
-- Follow the codex-job replacement and its CI-collected launcher proof.
-- GENERATED by ops/sync_control_catalog.py; never hand-edit.
insert into ops.enforcement_control_catalog
    (control_key, implementation_ref, test_ref, enforcement_class, installed, verified_at, updated_at)
values ('delegation_names_model_and_effort', 'bin/codex-job', 'tools/test-codex-job.py', 'deny_gate', true, now(), now())
on conflict (control_key) do update set
    implementation_ref = excluded.implementation_ref,
    test_ref           = excluded.test_ref,
    enforcement_class  = excluded.enforcement_class,
    installed          = excluded.installed,
    verified_at        = excluded.verified_at,
    updated_at         = now();
